def transform(grid):
    h = len(grid)
    w = len(grid[0]) if h > 0 else 0
    result = [row[:] for row in grid]

    # Find background color (most frequent)
    from collections import Counter
    bg_count = Counter()
    for r in range(h):
        for c in range(w):
            bg_count[grid[r][c]] += 1
    bg_color = bg_count.most_common(1)[0][0]

    # Find pattern: extract non-background values from row with most of them
    pattern_list = []
    for r in range(h):
        non_bg = [grid[r][c] for c in range(w) if grid[r][c] != bg_color]
        if len(non_bg) >= 2:
            pattern_list = non_bg
            break

    if not pattern_list:
        return result

    # Find trigger locations (scattered non-background values with count >= 3)
    trigger_vals = Counter()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg_color:
                trigger_vals[grid[r][c]] += 1

    trigger_val = None
    max_count = 0
    for v, cnt in trigger_vals.items():
        if cnt >= 3 and cnt > max_count:
            max_count = cnt
            trigger_val = v

    if trigger_val is None:
        return result

    # Place pattern centered at each trigger position
    pattern_len = len(pattern_list)
    half = pattern_len // 2

    for r in range(h):
        for c in range(w):
            if grid[r][c] == trigger_val:
                # Place pattern centered at this column
                for i, val in enumerate(pattern_list):
                    offset = i - half
                    nc = c + offset
                    if 0 <= nc < w:
                        result[r][nc] = val

    return result
